92: // NewBrowser creates a new browser. Typically, this function wouldn't be called
93: // directly, as the Allocator interface takes care of it.
94: func NewBrowser(ctx context.Context, urlstr string, opts ...BrowserOption) (*Browser, error) {
95: 	b := &Browser{
96: 		LostConnection:    make(chan struct{}),
97: 		closingGracefully: make(chan struct{}),
98: 
99: 		dialTimeout: 10 * time.Second,
100: 
101: 		newTabQueue: make(chan *Target),
102: 
103: 		// Fit some jobs without blocking, to reduce blocking in Execute.
104: 		cmdQueue: make(chan *cdproto.Message, 32),
105: 
106: 		logf: log.Printf,
107: 	}
108: 	// apply options
109: 	for _, o := range opts {
110: 		o(b)
111: 	}
112: 	// ensure errf is set
113: 	if b.errf == nil {
114: 		b.errf = func(s string, v ...any) { b.logf("ERROR: "+s, v...) }
115: 	}
116: 
117: 	dialCtx := ctx
118: 	if b.dialTimeout > 0 {
119: 		var cancel context.CancelFunc
120: 		dialCtx, cancel = context.WithTimeout(ctx, b.dialTimeout)
121: 		defer cancel()
122: 	}
123: 
124: 	var err error
125: 	b.conn, err = DialContext(dialCtx, urlstr, WithConnDebugf(b.dbgf))
126: 	if err != nil {
127: 		return nil, fmt.Errorf("could not dial %q: %w", urlstr, err)
128: 	}
129: 
130: 	go b.run(ctx)
131: 	return b, nil
132: }
