134: // Process returns the process object of the browser.
135: //
136: // It could be nil when the browser is allocated with RemoteAllocator.
137: // It could be useful for a monitoring system to collect process metrics of the browser process.
138: // (See [prometheus.NewProcessCollector] for an example).
139: //
140: // Example:
141: //
142: //	if process := chromedp.FromContext(ctx).Browser.Process(); process != nil {
143: //		fmt.Printf("Browser PID: %v", process.Pid)
144: //	}
